function context(extra=[],untilId,allowMemory=false,includeRecall=true){let selected=[],count=0,imageChars=0;const end=untilId?state.messages.findIndex(m=>m.id===untilId):-1,history=untilId?state.messages.slice(0,end+1):state.messages,eligible=history.filter(m=>(m.content||m.withdrawn)&&!m.pending),pool=[...eligible,...extra],limit=Math.min(12000,Math.max(5000,state.settings.contextChars));for(const m of pool.slice(-24).reverse()){const size=(m.parts||[]).filter(p=>p.type==='image').reduce((n,p)=>n+p.src.length,0),textSize=messageText(m).length;if(count+textSize>limit||imageChars+size>16*1024*1024)break;selected.unshift(m);count+=textSize;imageChars+=size}while(selected.length&&selected[0].role==='assistant')selected.shift();const memoryCheck=allowMemory&&state.settings.aiMemory&&(state.stats.turns+1-state.memoryMeta.lastExtractionTurn)>=16,lastIndex=eligible.findIndex(m=>m.id===state.memoryMeta.lastExtractionMessageId),memorySourceIds=(lastIndex>=0?eligible.slice(lastIndex+1):eligible.slice(-32)).map(m=>m.id).filter(Boolean).slice(-40),recall=includeRecall?memoryRecall(pool):{core:[],records:[],ids:[]},system=['用户设备当前时间：'+new Date().toLocaleString('zh-CN',{hour12:false})+'；动态和消息时间以本机记录为准，不虚构真实活动。你不能直接查看页面的视觉排版，但可以读取下方按当前话题召回的朋友圈、评论和信件文字。没有召回记录时，不要声称看过未提供的历史。'];const health=healthPrompt();if(health)system.push(health);if(recall.core.length)system.push('需要稳定保持的核心记忆（用户可编辑或置顶）：\n'+recall.core.map(m=>'['+m.id+'] '+m.text).join('\n'));if(recall.records.length)system.push('根据当前话题从本机找回的相关记录，只在确实相关时自然使用，不要逐条复述：\n'+recall.records.map(doc=>'['+(doc.kind==='memory'?MEMORY_LABELS[doc.type]:doc.kind==='feed'?'朋友圈':'信件')+' '+doc.id+'] '+doc.text).join('\n\n'));if(memoryCheck)system.push(memoryExtractionPrompt());if(state.settings.interactions){system.push('此聊天界面支持可选的虚拟互动，无实际金钱和订单。自然聊天为主，不需要人设，也不强制使用互动。需要发一个表情时独占一行写 [[表情:ID]]，可用ID：'+allStickers().map(s=>s.id+'='+s.name).join('；')+'。发虚拟红包独占一行 [[红包:数额|祝福]]，数额0.01至10000。送虚拟外卖 [[外卖:餐品|留言]]。收到用户送的卡片可用 [[领取:卡片ID]] 领取，只能领取用户发送且未领取的卡片。想戳一戳用户时独占一行写 [[戳一戳]]。可发语音条独占一行 [[语音:要说的话]]（最多2000字），由用户点击浏览器朗读，文字同时显示。推荐音乐写 [[音乐:歌名|歌手|推荐理由]]，这只是分享卡片，不是已播放的音频。你也可以自愿撤回自己之前的消息：[[撤回:消息ID]]，或撤回当前这条 [[撤回:自己]]；不能撤回用户消息，不必因为用户撤回就跟着撤回。可撤回的你的消息ID：'+state.messages.filter(m=>m.role==='assistant'&&!m.withdrawn&&!m.pending).slice(-20).map(m=>m.id+'='+m.content.slice(0,40)).join('；')+'。以上都是你自愿表达的互动，不是你的内部思维。')}return {messages:[...(system.length?[{role:'system',content:system.join('\n\n')}]:[]),...selected.map(apiMessage)],memoryCheck,memorySourceIds,recallIds:recall.ids,included:selected.length,total:pool.length};}
function restoreViewScroll(view,current,sameRoute,previousScroll){if(sameRoute){view.scrollTop=previousScroll;return}if(current==='chat'){requestAnimationFrame(()=>{if(route()==='chat')bottom()});return}view.scrollTop=0}
function render(){const r=route(),view=$('#view'),sameRoute=renderedRoute===r,previousScroll=view.scrollTop;const navigation=$('#navigation');$('#app').dataset.route=r;$('#feed-topbar').hidden=r!=='feed';if(!navigation.children.length)$('#navigation').innerHTML=NAV.map(([path,i,n])=>`<a href="#${path}" class="nav-item ${r===path?'active':''}" ${r===path?'aria-current="page"':''}>${luneIcon('nav-'+path)}<span>${n}</span></a>`).join('');navigation.querySelectorAll('.nav-item').forEach(link=>{const active=link.getAttribute('href')==='#'+r;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')});$('#connection').textContent=busy?'正在回复':apiKey?'已配置 API':'未配置 API';$('#connection').classList.toggle('ready',!!apiKey);$('#composer').hidden=r!=='chat';view.innerHTML=({home:homeView,chat:chatView,feed:feedView,whisper:letterView,memory:memoryView,health:healthView,settings:settingsView,'profile-user':()=>profilePage('user'),'profile-ai':()=>profilePage('assistant')}[r]||homeView)();renderedRoute=r;restoreViewScroll(view,r,sameRoute,previousScroll);updateComposer();updateClock();setupHomeAudio();animateRoute(r);}
function homeView(){const s=state.settings,now=new Date(),hr=now.getHours(),greeting=hr<11?'早上好':hr<18?'下午好':'晚上好',usable=state.memories.filter(m=>memoryActive(m)).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||new Date(b.updatedAt||b.at)-new Date(a.updatedAt||a.at)),mem=usable[0],letter=state.letters.at(-1),journal=mem?.text||letter?.content||'今天也想留下一件值得记住的小事。',notes=usable.slice(0,1);return `<section class="home-intro"><div class="home-portraits">${avatar('user',true)}${luneIcon('heart','portrait-heart')}${avatar('assistant',true)}</div><div class="home-greeting"><p class="date">${now.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</p><h1>${greeting}，<span>${esc(s.userName)}</span></h1></div></section><section class="lune-hero" aria-label="今天的手账和照片"><button class="lune-polaroid" type="button" data-action="polaroid-toggle" aria-expanded="false" aria-label="抽出拍立得查看照片"><img src="assets/lune/polaroid-card.png?v=53" alt="月亮与白色小花拍立得"><span>我们的小小瞬间</span><small>轻点抽出</small></button><a class="lune-diary" href="#memory"><img class="diary-paper" src="assets/lune/diary-paper.png?v=53" alt=""><div class="diary-copy"><div class="diary-date"><strong>${now.toLocaleDateString('zh-CN',{month:'long',day:'numeric'})}</strong><span>${now.toLocaleDateString('zh-CN',{weekday:'long'})}</span></div><h2>今天的小事</h2><p>${esc(journal.slice(0,74))}</p><span class="diary-more">读这一页 ${luneIcon('chevron-right')}</span></div></a></section><section class="home-bento"><div class="home-memory"><div class="home-block-title"><h2>共同记忆</h2><a href="#memory" aria-label="查看共同记忆">${luneIcon('chevron-right')}</a></div><div class="memory-preview-list">${notes.length?notes.map((note,index)=>`<a href="#memory" class="memory-preview">${luneIcon('heart')}<span><strong>${esc(note.text.slice(0,16))}</strong><small>${esc(note.text.slice(16,48)||'留在我们的时间线里。')}</small></span></a>`).join(''):`<a href="#memory" class="memory-preview">${luneIcon('heart')}<span><strong>还没有共同记忆</strong><small>聊着聊着，他会留下想记住的小事。</small></span></a>`}</div></div><div class="home-listen"><div class="home-block-title"><h2>一起听</h2><button data-action="home-music-edit" aria-label="设置一起听">${luneIcon('chevron-right')}</button></div>${homeMusic()}</div></section>${healthHome()}<div class="home-footer"><span>所有记录保存在这台设备</span><a class="quiet" href="#settings">设置 ${luneIcon('chevron-right')}</a></div>`}
function splitReplyText(text){const lines=String(text??'').trim().split(/\n+/).map(line=>line.trim()).filter(Boolean),result=[];for(const line of lines){if([...line].length<=120){result.push(line);continue}const sentences=line.match(/[^。！？!?；;]+[。！？!?；;]?/g)||[line];let chunk='';for(const sentence of sentences){if(chunk&&[...(chunk+sentence)].length>100){result.push(chunk.trim());chunk=''}chunk+=sentence}if(chunk.trim())result.push(chunk.trim())}return result}
function pushTextParts(parts,text){for(const block of splitReplyText(text))parts.push({type:'text',text:block})}
function memoryType(value){return {事实:'fact',经历:'episode',待续:'thread'}[value]||''}
function memoryKeywords(value){return String(value||'').split(/[,，、]/).map(v=>[...v.trim()].slice(0,12).join('')).filter(Boolean).slice(0,6)}
function processMemoryMarkers(raw,m){let changes=0;const seen=m.memoryMarkers??=[],sourceIds=[...new Set([...(m.memorySourceIds||[]),m.id].filter(Boolean))].slice(-40),cleaned=String(raw||'').replace(/\[\[记忆:([^\]\r\n]*)\]\]/g,(marker,body)=>{if(!state.settings.aiMemory||m.role!=='assistant'||!m.memoryCheck||seen.includes(marker))return '';if(changes>=3){seen.push(marker);return ''}const fields=body.split('|').map(v=>v.trim()),action=fields[0];if(action==='新增'){const type=memoryType(fields[1]),text=[...String(fields[2]||'')].slice(0,120).join(''),keywords=memoryKeywords(fields[3]);if(type&&[...text].length>=2&&!state.memories.some(item=>item.text.replace(/\s/g,'')===text.replace(/\s/g,''))){state.memories.push(memoryOf({id:id(),text,type,keywords,origin:'assistant',sourceIds,at:stamp(),confidence:'candidate',tier:'short',strength:30}));changes++}}else if(action==='更新'){const item=state.memories.find(item=>item.id===fields[1]&&item.origin==='assistant'&&!item.pinned),text=[...String(fields[2]||'')].slice(0,120).join('');if(item&&[...text].length>=2){item.text=text;item.keywords=memoryKeywords(fields[3]);item.updatedAt=stamp();item.sourceIds=sourceIds;item.reviewNeeded=false;item.enabled=true;item.confidence='candidate';item.tier='short';changes++}}else if(action==='完成'){const item=state.memories.find(item=>item.id===fields[1]&&item.type==='thread'&&item.origin==='assistant'&&!item.pinned);if(item){item.status='resolved';item.updatedAt=stamp();changes++}}seen.push(marker);return ''});m.memoryMarkers=seen;m.memorySavedCount=changes;return cleaned}
function stagedPiece(html){return html.replace('>',' data-staged-piece>')}
function replyActionsHTML(m,hasContent){if(m.role!=='assistant'||m.pending)return '';const recovering=m.failed||m.partial;return `${recovering?`<button data-action="regenerate" data-id="${m.id}" ${busy?'disabled':''}>重新生成</button>`:''}${recovering&&hasContent?`<button data-action="continue" data-id="${m.id}" ${busy?'disabled':''}>继续说完</button>`:''}${hasContent?`<button data-action="keep" data-id="${m.id}">记住</button><button data-action="voice-read" data-id="${m.id}">朗读</button>`:''}`}
function editableUserMessage(m){return !!m&&m.role==='user'&&!m.withdrawn&&String(m.content||'').trim()&&!(m.parts||[]).some(p=>p.type!=='text')}
function messageHTML(m){if(m.withdrawn)return `<div class="withdrawn-message">${esc(m.role==='user'?state.settings.userName:state.settings.aiName)} 撤回了一条消息</div>`;if(m.parts?.length===1&&m.parts[0].type==='poke')return pokeHTML(m);const waiting=m.pending&&!String(m.content||'').trim()&&!m.parts?.length,sourceParts=m.parts||splitReplyText(m.content).map(text=>({type:'text',text})),hasContent=sourceParts.length>0,failed=m.role==='assistant'&&!m.pending&&m.failed,pieces=waiting?`<div class="bubble typing-bubble" role="status" aria-label="正在输入"><span>正在输入</span><span class="typing-dots" aria-hidden="true"><i></i><i></i><i></i></span></div>`:failed&&!hasContent?`<div class="reply-failed" role="alert"><strong>回复中断了</strong><span>${esc(m.failure||'这次没有收到完整回复。')}</span></div>`:sourceParts.map((p,partIndex)=>stagedPiece(p.type==='text'?`<div class="bubble">${m.role==='assistant'&&!m.pending?`<button class="bubble-text" data-action="quote" data-id="${m.id}" data-part="${partIndex}" aria-label="引用这条消息">${markdown(p.text)}</button>`:esc(p.text)}</div>`:p.type==='claim'?claimHTML(m,p):p.type==='sticker'?stickerHTML(allStickers().find(s=>s.id===p.stickerId),p.animated):p.type==='poke'?pokeHTML(m):p.type==='memory'?`<a class="memory-saved" href="#memory">${icon('bookmark')} ${esc(p.text||'记下了一件小事')}</a>`:p.type==='voice'?voiceHTML(m,p):p.type==='music'?musicHTML(p):p.type==='file'?fileHTML(m,p):['image','video'].includes(p.type)?mediaHTML(p):cardHTML(m,p))).join('');return `<article class="message ${m.role==='user'?'user':''} ${freshMessageId===m.id?'fresh':''}" data-bubble="${m.role==='user'?(state.settings.userBubble||state.settings.bubble):(state.settings.aiBubble||state.settings.bubble)}" data-message-id="${m.id}">${avatar(m.role)}<div class="message-body">${m.quote?quoteHTML(m.quote):''}${pieces}${waiting?'':`<div class="message-meta" data-staged-piece><span>${new Date(m.at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}${m.edited?' · 已修改':''}${failed?' · 回复中断':m.partial?' · 回复未完成':''}</span>${hasContent?`<button data-action="copy" data-id="${m.id}">复制</button>`:''}${m.role==='user'?`${editableUserMessage(m)?`<button data-action="message-edit" data-id="${m.id}" ${busy?'disabled':''}>修改</button><button data-action="message-delete" data-id="${m.id}" ${busy?'disabled':''}>删除</button>`:''}<button data-action="withdraw" data-id="${m.id}" ${busy?'disabled':''}>撤回</button>`:replyActionsHTML(m,hasContent)}</div>`}</div></article>`}
function cardHTML(m,p){const gift=p.type==='gift',received=p.received,canReceive=m.role==='assistant'&&!received;return `<button class="virtual-card ${gift?'gift':'food'}" data-action="receive" data-id="${m.id}" data-card="${p.id}" ${canReceive?'':'disabled'}>${icon(gift?'mail':'heart')}<div><strong>${gift?'一个小红包':'给你点了外卖'}</strong><span>${gift?'¥ '+Number(p.amount).toFixed(2):esc(p.item)}</span><small>${esc(p.note)}</small></div><em>${received?'已领取':canReceive?'点开领取':'等待对方领取'} · 虚拟</em></button>`}
function claimHTML(m,p){const gift=p.cardType==='gift',mine=m.role==='user';return `<div class="virtual-card ${gift?'gift':'food'} claim-card">${icon(gift?'mail':'heart')}<div><strong>${mine?(gift?'已领取红包':'已领取外卖'):(gift?'已领取你的红包':'已领取你的外卖')}</strong><span>${gift?'¥ '+Number(p.amount).toFixed(2):esc(p.item)}</span><small>${esc(p.note||'已经收到啦。')}</small></div><em>已领取 · 虚拟</em></div>`}
function chatView(){const s=state.settings;return `<div class="chat-head">${avatar('assistant')}<div><h1>${esc(s.aiName)}</h1><p>不设人设，直接聊</p></div><button class="quiet" data-action="chat-menu">更多</button></div>${selectionMode?`<div class="selection-tools"><button class="quiet" data-action="select-all">全选</button><button class="quiet" id="delete-selected" data-action="delete-selected" ${selectedMessageIds.size?'':'disabled'}>删除 (${selectedMessageIds.size})</button><button class="quiet" data-action="select-cancel">取消</button></div>`:''}${state.messages.length?`<div class="chat-date">我们的对话</div><div class="messages">${state.messages.map(m=>selectionMode?`<div class="selectable-message"><label class="message-check"><input type="checkbox" data-message-select="${m.id}" ${selectedMessageIds.has(m.id)?'checked':''} aria-label="选择这条${m.role==='user'?'我的':'对方的'}消息"></label>${messageHTML(m)}</div>`:messageHTML(m)).join('')}</div>`:`<div class="chat-empty">${avatar('assistant',true)}<h2>今天想聊什么？</h2><p>一件小事，或一大段心情。<br>可以一段段发送，说完再点「让他回复」。</p>${!apiKey?'<button class="primary" data-action="settings-api">连接我的 API</button>':'<button class="secondary" data-action="focus">开始写</button>'}<div class="chat-tip">${stickerHTML(lineDogs[0]||presets[0])}<span>表情、红包和虚拟外卖<br>就在下方，点一下就能发送。</span></div></div>`}${errorText?`<div class="error-banner" role="alert">${esc(errorText)}<small>可在中断消息下方重新生成，已有部分内容时也可以继续说完。</small></div>`:''}`}
function feedView(){const s=state.settings;return `<section class="feed-paper-banner"><div class="feed-pair">${avatar('user',true)}${luneIcon('heart','feed-pair-heart')}${avatar('assistant',true)}</div><div class="feed-banner-copy"><h2>我们的最近</h2><p>记录生活里，一起度过的每个日常。</p></div><img class="feed-banner-flower" src="assets/lune/feed-flower.png" alt="" aria-hidden="true"></section><section class="feed-compose">${avatar('user')}<button class="feed-compose-prompt" data-action="status-write">记录今天的小事…</button><button class="feed-compose-photo" data-action="status-write" aria-label="写说说">${icon('photo')}</button></section><div class="feed-ai-row"><button data-action="feed-generate" ${busy?'disabled':''}>${busy?'正在写下一条动态…':'让 '+esc(s.aiName)+' 留下一条动态'} ${icon('chevron-right')}</button><small>会调用一次 API${s.imageModel?'，需要配图时可能再调用一次':''}</small></div><section class="feed-stream">${state.feed.length?state.feed.slice().reverse().map(postHTML).join(''):`<div class="feed-empty"><h2>还没有动态</h2><p>写一条说说，留住今天的小事。</p><button data-action="status-write">写第一条说说</button></div>`}</section>`}
function postHTML(p){const who=p.role==='user'?'user':'assistant',name=who==='user'?state.settings.userName:state.settings.aiName,at=new Date(p.at),comments=p.comments||[],postImage=feedImageUrl(p.image);return `<article class="feed-post">${avatar(who)}<div class="feed-content"><header><div><h3>${esc(name)}</h3><time>${at.toLocaleDateString('zh-CN',{month:'long',day:'numeric'})} ${at.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})}</time></div><span class="feed-more" aria-hidden="true">•••</span></header><div class="feed-post-text rich-content">${richContent(p.content)}</div>${postImage?`<img class="feed-post-image" src="${esc(postImage)}" alt="朋友圈配图" loading="lazy">`:''}${p.mood?`<small class="post-mood">${esc(p.mood)}</small>`:''}<div class="feed-meta"><button data-action="feed-like" data-id="${p.id}" aria-label="${p.liked?'取消喜欢':'喜欢'}" aria-pressed="${p.liked?'true':'false'}"><span class="feed-like-heart">${icon('heart')}</span><span>${p.liked?'1':''}</span></button><button data-action="feed-comment" data-id="${p.id}" aria-label="评论">${icon('message-circle')}<span>${comments.length||''}</span></button></div>${comments.map(c=>`<div class="feed-comment rich-content"><strong>${esc(state.settings.userName)}：</strong>${richContent(c)}</div>`).join('')}</div></article>`}
function profilePage(who){const user=who==='user',s=state.settings,profile=state.profiles[who],name=user?s.userName:s.aiName,sticker=lineDogs.find(p=>p.id===profile.moodSticker),posts=state.feed.filter(p=>(p.role||'assistant')===who);return `<div class="profile-nav"><a class="quiet" href="#chat">${icon('arrow-left')} 聊天</a><button class="quiet" data-action="profile-edit" data-who="${who}">编辑资料</button></div><section class="person-cover">${avatar(who,true,false)}<h1>${esc(name)}</h1><p>${esc(profile.bio||'在这里，留一点自己的日常。')}</p><button class="person-mood" data-action="profile-edit" data-who="${who}" aria-label="编辑${esc(name)}的心情">${sticker?stickerHTML(sticker):icon('heart')}<span>${esc(profile.mood||'写下今天的心情')}</span></button></section><div class="section-head"><div><h2>${user?'我的说说':'他的朋友圈'}</h2><p>${posts.length} 条小日常</p></div><button class="quiet" data-action="${user?'status-write':'feed-generate'}" ${!user&&busy?'disabled':''}>${user?'写说说':'生成动态'}</button></div>${posts.length?posts.slice().reverse().map(postHTML).join(''):empty('photo','还没有动态',user?'今天的心情，想写一点吗？':'点「生成动态」，让他留下一条日常。')}`}
function profileModal(who){const p=state.profiles[who],name=who==='user'?state.settings.userName:state.settings.aiName;openModal('编辑 '+esc(name)+' 的资料',`<form id="person-form" data-who="${who}">${field('bio','一句话介绍','text',p.bio,'maxlength="160"')}${field('mood','今天的心情','text',p.mood,'maxlength="80" placeholder="比如：今天有一点想你"')}<input hidden name="moodSticker" value="${esc(p.moodSticker)}"><label class="form-field"><span>选一只心情小狗</span></label><div class="mood-picker">${[6,8,10,11,3,15,7,12].map(n=>lineDogs.find(p=>p.id==='linedog-'+String(n).padStart(2,'0'))).filter(Boolean).map(sticker=>`<button type="button" data-action="mood-pick" data-id="${sticker.id}" aria-pressed="${p.moodSticker===sticker.id}" class="${p.moodSticker===sticker.id?'selected':''}">${stickerHTML(sticker)}<small>${esc(sticker.name)}</small></button>`).join('')}</div><button type="button" class="quiet" data-action="mood-pick" data-id="">不用图标</button><button class="primary wide">保存资料和心情</button><p class="notice">由你编辑并保存在本机，不调用 API。</p></form>`)}
function statusModal(){openModal('写一条说说',`<form id="status-form"><label class="form-field"><span>今天想留下什么？</span><textarea name="content" rows="5" required maxlength="200" placeholder="一点小事，一点心情……（200字以内）"></textarea></label><label class="upload-btn wide">${icon('photo')} 配一张图片<input hidden name="photo" type="file" accept="image/png,image/jpeg,image/webp"></label><button class="primary wide">发布说说</button><p class="notice">文字和图片保存在你的小手机里，不发布到 QQ 或其他平台，不调用 API。</p></form>`)}
const LETTER_THEMES={
  normal:{key:'normal',name:'一封普通的信',intro:'把最近想说的话，认真写下来。',prompt:'围绕最近的相处和此刻最想表达的话来写，像一封值得留下来的私密长信。'},
  serious:{key:'serious',name:'想认真说的话',intro:'写一封更认真、更完整的信。',prompt:'写下平时没有完整说出口的重要感受，语气真诚、克制而温柔。'},
  'first-snow':{key:'first-snow',name:'第一场雪',intro:'把初雪变成一封冬天的信。',prompt:'以第一场雪为主题，写冬日的想念、陪伴和想一起完成的小事；不要声称真的看见了雪。'},
  cherry:{key:'cherry',name:'樱花季',intro:'写一封带着春天气息的信。',prompt:'以樱花季和春天为主题，写相伴、期待和想一起珍藏的春日瞬间；不要虚构已经共同去过的地点。'},
  '1314':{key:'1314',name:'1314 · 一生一世',intro:'任何一天，都可以认真说一次长久。',prompt:'围绕长久陪伴和一生一世的心意来写，避免空泛誓言，用共同聊天里的小事承载感情。'}
};
const FIXED_OCCASIONS={
  '01-01':{key:'new-year',name:'元旦',intro:'新的一年，写下想一起走向的日子。',prompt:'回顾过去一段相处，也写下新一年的祝福、期望和想一起完成的小事。'},
  '02-14':{key:'valentine',name:'情人节',intro:'今天适合把喜欢认真写下来。',prompt:'围绕喜欢、心动和陪伴来写，结合真实共同记忆，让情感具体而不空泛。'},
  '03-14':{key:'white-day',name:'白色情人节',intro:'回应那些被好好接住的心意。',prompt:'围绕回应、珍惜和双向的陪伴来写，像对曾收到的温柔认真回信。'},
  '03-20':{key:'spring-equinox',name:'春分',intro:'春天正好走到一半。',prompt:'以春分和渐暖的季节为线索，写关系里正在生长的温柔与期待。'},
  '05-20':{key:'520',name:'520',intro:'把“我爱你”写得更具体一点。',prompt:'围绕“我爱你”写一封不空泛的信，用共同聊天中的细节表达在意。'},
  '05-21':{key:'521',name:'521',intro:'再认真说一次喜欢。',prompt:'围绕喜欢与被喜欢的回应来写，语气亲密自然，落在真实相处的小事上。'},
  '06-01':{key:'children-day',name:'儿童节',intro:'今天可以放心可爱，也可以撒娇。',prompt:'写一封轻松可爱的信，允许一点撒娇和童心，也表达想保护对方柔软一面的心意。'},
  '06-21':{key:'summer-solstice',name:'夏至',intro:'白昼最长的时候，也想多陪你一会儿。',prompt:'以夏至和漫长白昼为线索，写夏日陪伴、惦念和想一起度过的平凡时刻。'},
  '09-22':{key:'autumn-equinox',name:'秋分',intro:'风开始变凉，话适合慢慢写。',prompt:'以秋分和渐凉的季节为线索，写安稳陪伴、收获与想继续珍惜的日常。'},
  '10-31':{key:'halloween',name:'万圣节',intro:'写一封有一点搞怪的节日信。',prompt:'带一点万圣节的俏皮、恶作剧和可爱想象，同时保留真诚的亲密感。'},
  '12-21':{key:'winter-solstice',name:'冬至',intro:'天冷了，把惦念写得暖一点。',prompt:'以冬至和寒冷季节为线索，写关心、陪伴与想一起吃饭过冬的温暖。'},
  '12-24':{key:'christmas-eve',name:'平安夜',intro:'今晚最想送出的，是一句平安。',prompt:'围绕平安、守候和夜晚的祝福来写，温柔而有仪式感。'},
  '12-25':{key:'christmas',name:'圣诞节',intro:'把祝福和喜欢装进一封信。',prompt:'带一点圣诞氛围，写祝福、礼物般的心意和想一起度过的冬日。'},
  '12-31':{key:'new-years-eve',name:'跨年夜',intro:'在一年结束前，留下一封长信。',prompt:'回顾这一年的共同记忆和感受，写下感谢、珍惜以及对下一年的期待。'}
};
function dateOnly(value){const match=String(value||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);return match?new Date(Number(match[1]),Number(match[2])-1,Number(match[3])):null}
function localDateKey(date){return [date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-')}
function monthDay(date){return localDateKey(date).slice(5)}
function sameMonthDay(value,date){const saved=dateOnly(value);return !!saved&&saved.getMonth()===date.getMonth()&&saved.getDate()===date.getDate()}
function relationshipStart(){const saved=dateOnly(state.settings.relationshipDate);if(saved)return saved;const first=state.messages.map(m=>new Date(m.at)).filter(d=>Number.isFinite(d.getTime())).sort((a,b)=>a-b)[0];return first?new Date(first.getFullYear(),first.getMonth(),first.getDate()):null}
function daysTogether(start,date){return Math.floor((Date.UTC(date.getFullYear(),date.getMonth(),date.getDate())-Date.UTC(start.getFullYear(),start.getMonth(),start.getDate()))/86400000)+1}
function qixi(date){try{const parts=Object.fromEntries(new Intl.DateTimeFormat('zh-CN-u-ca-chinese',{month:'numeric',day:'numeric'}).formatToParts(date).map(part=>[part.type,part.value]));return Number(parts.month)===7&&Number(parts.day)===7}catch{return false}}
function festivalOccasion(date=new Date()){
  const dated=localDateKey(date),md=monthDay(date),start=relationshipStart(),days=start&&date>=start?daysTogether(start,date):0;
  if(sameMonthDay(state.settings.userBirthday,date))return {key:'user-birthday',name:state.settings.userName+'的生日',intro:'今天，把最特别的祝福写给你。',prompt:'这是收信人的生日。写一封庆祝、珍惜并感谢对方存在的生日信，结合真实共同记忆，不虚构现实安排。',date:dated};
  if(sameMonthDay(state.settings.aiBirthday,date))return {key:'ai-birthday',name:state.settings.aiName+'的生日',intro:'今天也值得留下一封特别的信。',prompt:'这是写信者被设定的生日。以感谢对方陪伴、分享此刻感受和对未来相处的期待为重点写信，不声称拥有真实身体或现实经历。',date:dated};
  if(start&&md===monthDay(start)&&date.getFullYear()>start.getFullYear())return {key:'anniversary-'+(date.getFullYear()-start.getFullYear()),name:(date.getFullYear()-start.getFullYear())+'周年纪念日',intro:'从第一次聊天到今天，又走过了一整年。',prompt:'这是相识周年纪念日。回顾真实共同记忆、关系里的变化和感受，也认真写下对下一年的期待。',date:dated};
  if(days>=100&&days%100===0)return {key:'days-'+days,name:days+'天纪念日',intro:'一起走过的日子，值得被认真记住。',prompt:'这是相识第 '+days+' 天。结合真实共同记忆，写下这段时间里感受到的陪伴、变化与珍惜。',date:dated};
  if(qixi(date))return {key:'qixi',name:'七夕',intro:'今晚，把东方的浪漫写进信里。',prompt:'以七夕为主题，用含蓄温柔的东方浪漫表达喜欢、牵挂与长久陪伴，结合真实共同记忆。',date:dated};
  if(FIXED_OCCASIONS[md])return {...FIXED_OCCASIONS[md],date:dated};
  if(start&&date>start&&date.getDate()===start.getDate())return {key:'monthly-'+dated.slice(0,7),name:'月度纪念日',intro:'每个月的这一天，都再记住一次相遇。',prompt:'这是每月的相识纪念日。回顾最近一个月真实聊过的事，写下新的感受、感谢和下个月的期待。',date:dated};
  return null
}
function festivalPromptKey(occasion){return occasion?occasion.date+'|'+occasion.key:''}
async function maybeFestivalPrompt(){const occasion=festivalOccasion(),key=festivalPromptKey(occasion),written=occasion&&state.letters.some(letter=>letter.occasionKey===occasion.key&&letter.occasionDate===occasion.date);if(!occasion||written||state.settings.festivalPrompted===key||$('#modal').open)return;state.settings.festivalPrompted=key;await save();openModal('一封节日邀请',`<section class="festival-invite">${avatar('assistant',true,false)}<small>${esc(state.settings.aiName)} · ${esc(occasion.name)}</small><h2>今天是${esc(occasion.name)}，<br>我想认真给你写一封信。</h2><p>${esc(occasion.intro)}</p></section><div class="festival-invite-actions"><button class="secondary" data-action="close">晚点再说</button><button class="primary" data-action="festival-accept">收下这封信</button></div><p class="notice">选择收下后才会调用一次 API；晚点也可以在心里话里找到节日入口。</p>`)}
function festivalReadyModal(letter,occasion){openModal('信已经写好了',`<section class="festival-ready">${luneIcon('heart')}<small>${esc(occasion.name)}</small><h2>我把想说的话写进信里了。</h2><p>去心里话里拆开它吧。</p></section><button class="primary wide" data-action="festival-collect" data-id="${letter.id}">去心里话收信</button>`)}
function letterThemeModal(){const occasion=festivalOccasion(),themes=[...(occasion?[occasion]:[]),...['normal','serious','first-snow','cherry','1314'].map(key=>LETTER_THEMES[key])];openModal('想写一封怎样的信？',`<div class="letter-theme-list">${themes.map(theme=>`<button data-action="letter-theme" data-theme="${esc(theme.key)}" class="letter-theme-choice"><span>${luneIcon(theme===occasion?'heart':theme.key==='first-snow'?'badge-health':'badge-memory')}</span><strong>${esc(theme.name)}</strong><small>${esc(theme.intro)}</small>${luneIcon('chevron-right')}</button>`).join('')}</div><button class="quiet wide" data-action="festival-settings">设置生日与纪念日</button><p class="notice">选择主题后才会调用一次 API。节日当天会优先显示对应主题。</p>`)}
function festivalSettingsModal(){const start=relationshipStart(),derived=start?localDateKey(start):'';openModal('生日与纪念日',`<form id="festival-form">${field('userBirthday','你的生日','date',state.settings.userBirthday,'max="'+todayIso()+'"')}${field('aiBirthday',state.settings.aiName+' 的生日','date',state.settings.aiBirthday,'max="'+todayIso()+'"')}${field('relationshipDate','相识日期','date',state.settings.relationshipDate,'max="'+todayIso()+'" placeholder="'+derived+'"')}<button class="primary wide">保存日期</button><p class="notice">相识日期留空时，会使用现有聊天中最早的一天。月度纪念日、100 天和周年纪念会由它自动计算。</p></form>`)}
function letterView(){
  const letters=state.letters.slice().reverse(),latest=letters[0],history=letters.slice(1),labels=['给你的晚安','关于今天','没有说出口的话'],occasion=festivalOccasion(),occasionLetter=occasion&&letters.find(letter=>letter.occasionKey===occasion.key&&letter.occasionDate===occasion.date);
  const latestAction=latest?`data-action="letter-open" data-id="${latest.id}"`:`data-action="letter-generate" ${busy?'disabled':''}`;
  const historyHTML=history.length?history.map((letter,index)=>`<button class="whisper-letter-row" data-action="letter-open" data-id="${letter.id}"><span class="whisper-letter-mark tone-${index%3}">${luneIcon(index%3===0?'heart':index%3===1?'badge-health':'badge-memory')}</span><span class="whisper-letter-copy"><strong>${esc(letter.occasionName||labels[index]||'写给你的信')}</strong><small>${esc(plainContent(letter.content).slice(0,42))}</small></span><span class="whisper-letter-meta"><strong>${esc(state.settings.aiName)}</strong><time>${new Date(letter.at).toLocaleDateString('zh-CN',{month:'long',day:'numeric'})}</time></span>${luneIcon('chevron-right')}</button>`).join(''):`<p class="whisper-empty">写下第一封信后，往来的信会留在这里。</p>`;
  const holidayCard=occasion?`<section class="holiday-letter-card"><span class="holiday-letter-icon">${luneIcon('heart')}</span><div><small>今天 · ${esc(occasion.name)}</small><h2>${esc(occasion.intro)}</h2><p>${occasionLetter?'这封节日信已经写好，可以随时再读。':'不同的日子，会写下不同的心意。'}</p></div><button data-action="${occasionLetter?'letter-open':'festival-letter'}" ${occasionLetter?`data-id="${occasionLetter.id}"`:''} ${busy?'disabled':''}>${occasionLetter?'打开信':'写节日信'} ${luneIcon('chevron-right')}</button></section>`:'';
  return `<section class="whisper-head"><div><h1>写给彼此的话</h1><p>有些话，适合慢慢写下来。</p></div><button data-action="letter-generate" ${busy?'disabled':''} aria-label="选择信件主题">${icon('plus')}</button></section>${holidayCard}<div class="festival-status"><span>${luneIcon('badge-memory')} 节日主题信已开启</span><button data-action="festival-settings">设置日期</button></div><section class="whisper-feature"><img src="assets/lune/letter-envelope.png" alt=""><div class="whisper-feature-copy"><div class="whisper-sender"><strong>${esc(state.settings.aiName)}</strong><time>${latest?new Date(latest.at).toLocaleDateString('zh-CN',{month:'long',day:'numeric'}):'等一封信'}</time></div><h2>想认真告诉你的一件事</h2><button ${latestAction}>${latest?'拆开这封信':'写下第一封信'} <span>→</span></button></div></section><section class="whisper-history"><h2>往来的信</h2>${historyHTML}</section><button class="whisper-compose" data-action="letter-generate" ${busy?'disabled':''}>${icon('plus')}<span>${busy?'正在写…':'写一封信'}</span></button><p class="whisper-cost">选择主题后才会调用一次 API，可能按次收费。</p>`
}
function openedLetter(letter){
  const sent=new Date(letter.at||stamp()),date=[sent.getFullYear(),String(sent.getMonth()+1).padStart(2,'0'),String(sent.getDate()).padStart(2,'0')].join('.'),user=esc(state.settings.userName),ai=esc(state.settings.aiName);
  return `<div class="opened-letter-scroll"><article class="opened-letter"><img class="letter-torn-edge" src="assets/lune/letter-torn-edge.png" alt=""><img class="letter-blue-tape" src="assets/lune/letter-blue-tape.png" alt=""><img class="letter-postmark-flower" src="assets/lune/letter-postmark-flower.png" alt=""><header class="opened-letter-meta"><time>${date}</time><small>From ${ai} to ${user}</small></header><h2>给 ${user}：</h2><div class="letter-paper rich-content">${richContent(letter.content)}</div><footer class="opened-letter-footer"><span class="letter-footer-note">Same sky,<br>a kinder you.</span><span class="letter-signature">一直在，<br>${ai} ♡</span><img src="assets/linedog/65.png" alt="小狗贴纸"></footer></article></div>`
}
function memoryView(){const groups={fact:['fact','legacy'],episode:['episode'],thread:['thread']},memories=state.memories.filter(m=>groups[memoryFilter].includes(m.type)).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||Number(memoryActive(b))-Number(memoryActive(a))||new Date(b.updatedAt||b.at)-new Date(a.updatedAt||a.at)),tabs=[['fact','始终记得'],['episode','我们的经历'],['thread','下次接着聊']],now=Date.now();return `<section class="memory-page-head"><div><h1>共同记忆</h1><p>重要的留下，想起时再轻轻翻开。</p></div><button class="memory-page-add" data-action="memory-add" aria-label="手动添加记忆">＋</button></section><p class="memory-intro">最近 24 条消息保留原文；每 16 个有效回复整理一次记忆，不会额外调用 API。AI 的推测会先放进待确认区。</p>${switchField('aiMemory','使用分层记忆')}<nav class="memory-tabs" aria-label="记忆分类">${tabs.map(([value,label])=>`<button class="${memoryFilter===value?'active':''}" data-action="memory-filter" data-value="${value}" aria-pressed="${memoryFilter===value}">${label}<small>${state.memories.filter(m=>groups[value].includes(m.type)).length}</small></button>`).join('')}</nav><section class="memory-board">${memories.length?memories.map((m,index)=>{const expired=m.type==='thread'&&!m.pinned&&m.expiresAt&&Date.parse(m.expiresAt)<=now,recalled=m.lastRecalledAt&&now-Date.parse(m.lastRecalledAt)<7*86400000,source=m.origin==='user'?'手动记录':m.sourceIds.length?'来自聊天':'自动整理',stateLabel=m.reviewNeeded?'来源有变化 · 待确认':m.status==='resolved'?'已经聊完':expired?'已过期':m.confidence==='candidate'?'待确认':m.tier==='core'?'永久保存':m.tier==='stable'?'稳定记忆':'短期记忆';return `<article class="memory-note note-${index%7} ${m.enabled?'':'is-muted'} ${m.reviewNeeded?'needs-review':''}"><button class="memory-note-paper" data-action="memory-edit" data-id="${m.id}" aria-label="查看或编辑记忆：${esc(m.text)}"><span class="memory-note-kicker">${esc(MEMORY_LABELS[m.type])} · ${esc(stateLabel)}</span><p>${esc(m.text)}</p><time>${new Date(m.updatedAt||m.at).toLocaleDateString('zh-CN',{month:'long',day:'numeric'})} · ${source}${recalled?' · 最近想起':''}</time><span class="memory-doodle" aria-hidden="true"></span></button><div class="memory-note-tools"><button data-action="memory-pin" data-id="${m.id}" class="memory-heart ${m.pinned?'active':''}" aria-label="${m.pinned?'取消永久保存':'永久保存'}" aria-pressed="${m.pinned}">${m.pinned?'♥':'♡'}</button>${m.confidence==='candidate'||m.reviewNeeded?`<button data-action="memory-confirm" data-id="${m.id}" class="memory-confirm">确认</button>`:''}<label class="memory-pin" title="${m.enabled?'聊天中会使用':'聊天中不使用'}"><input type="checkbox" data-memory="${m.id}" ${m.enabled?'checked':''} aria-label="在聊天中使用这条记忆"><span aria-hidden="true">✓</span></label></div></article>`}).join(''):`<div class="memory-wait"><span></span><h2>这里还没有纸条</h2><p>${memoryFilter==='thread'?'以后想接着聊的话，会暂存在这里。':'聊着聊着，总有想记住的小事。'}</p></div>`}</section>`}
function choices(key,items){const fallback={userFont:'font',aiFont:'font',userFrame:'frame',aiFrame:'frame',userBubble:'bubble',aiBubble:'bubble'},current=state.settings[key]||state.settings[fallback[key]];return `<div class="choices">${items.map(([v,label,color])=>`<button class="choice ${current===v?'selected':''}" data-choice="${key}" data-value="${v}" aria-pressed="${current===v}">${color?`<span class="swatch" style="background:${color}"></span>`:''}${['frame','userFrame','aiFrame'].includes(key)?avatar(key==='userFrame'?'user':'assistant',false,false,v||state.settings.frame):''}${['font','userFont','aiFont'].includes(key)?`<span class="font-sample" style='font-family:${FONT_FAMILY[v||state.settings.font]}'>今天想你</span>`:''}${label}</button>`).join('')}</div>`}
function field(name,label,type='text',value=state.settings[name],extra=''){return `<label class="form-field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function switchField(name,label,sub=''){return `<div class="setting-row"><label for="set-${name}">${label}<small>${sub}</small></label><input class="switch" type="checkbox" id="set-${name}" data-setting="${name}" ${state.settings[name]?'checked':''}></div>`}
function settingsView(){return head('设置','把小手机换成喜欢的样子。')+`<div class="settings-tabs">${[['appearance','外观'],['profile','头像'],['api','API'],['data','资料']].map(([k,n])=>`<button data-tab="${k}" class="${tab===k?'active':''}">${n}</button>`).join('')}</div>`+({appearance:appearanceView,profile:profileView,api:apiView,data:dataView}[tab])()}
function appearanceView(){return `<section class="setting-section"><h2>主题颜色</h2>${choices('theme',[['blue','雾蓝','#dce7ee'],['rose','淡粉','#ecdce1'],['sage','浅绿','#dce5d3']])}${switchField('dark','夜间模式')}${switchField('motion','轻柔动效','页面切换和拍立得使用轻量动画；系统开启减少动态时会自动停用。')}</section><section class="setting-section"><div class="setting-title-row"><h2>聊天字体</h2><button class="quiet compact" data-action="unify-fonts">一键统一</button></div><h3 class="setting-subtitle">你的字体</h3>${choices('userFont',FONTS)}<h3 class="setting-subtitle">他的字体</h3>${choices('aiFont',FONTS)}<div class="setting-row"><label for="font-size">聊天字号</label><input id="font-size" type="range" min="14" max="22" value="${state.settings.size}" data-size><span>${state.settings.size}</span></div><small>一键统一会把他的字体设成你当前选择的字体。三款手写／圆体已随网页保存；首次选择需加载字体。</small></section><section class="setting-section"><h2>对话框</h2><h3 class="setting-subtitle">你的对话框</h3>${choices('userBubble',BUBBLES)}<h3 class="setting-subtitle">他的对话框</h3>${choices('aiBubble',BUBBLES)}</section><section class="setting-section"><h2>预览</h2><div class="preview-chat"><div class="message" data-bubble="${state.settings.aiBubble||state.settings.bubble}">${avatar('assistant')}<div class="bubble">今天的小事，也想听你说。</div></div><div class="message user" data-bubble="${state.settings.userBubble||state.settings.bubble}">${avatar('user')}<div class="bubble">那就慢慢聊。</div></div></div></section><section class="setting-section"><h2>背景图片</h2><label class="upload-btn">${icon('upload')} 上传背景<input hidden type="file" accept="image/png,image/jpeg,image/webp" data-upload="wallpaper"></label> <button class="quiet" data-action="wallpaper-clear">恢复纯色</button>${imageUrl(state.settings.wallpaper)?`<img class="wallpaper-thumb" src="${state.settings.wallpaper}" alt="背景预览">`:''}</section>`}
function profileView(){return `<form id="profile-form">${[['user','你的头像','userName','userAvatar'],['assistant','他的头像','aiName','aiAvatar']].map(([r,n,key,upload])=>`<section class="setting-section"><h2>${n}</h2><div class="profile-edit">${avatar(r,true)}${field(key,'显示名字')}</div><label class="upload-btn">${icon('upload')} 更换头像<input hidden type="file" accept="image/png,image/jpeg,image/webp" data-upload="${upload}"></label><button type="button" class="quiet" data-clear="${upload}">恢复首字头像</button></section>`).join('')}<button class="primary wide" type="submit">保存名字</button></form><div class="divider"></div><section class="setting-section"><div class="setting-title-row"><h2>头像框</h2><button class="quiet compact" data-action="unify-frames">一键统一</button></div><h3 class="setting-subtitle">你的头像框</h3>${choices('userFrame',FRAMES)}<h3 class="setting-subtitle">他的头像框</h3>${choices('aiFrame',FRAMES)}<small>一键统一会把他的头像框设成你当前选择的头像框。</small></section>`}
function apiView(){let remembered=false;try{remembered=!!localStorage.getItem('pocket-remembered-key')}catch{}return `<form id="api-form">${field('base','API 主机（OpenAI 兼容）','url')}${field('key','API 密钥','password',apiKey,'autocomplete="off"')}<label class="form-field"><span>聊天模型</span><div class="api-model-row"><select name="model" id="model-select" aria-label="选择聊天模型">${modelOptions(state.settings.model,state.settings.base)}</select><button class="secondary" type="button" data-action="models-fetch">拉取</button><button class="secondary" type="button" data-action="api-test">测试</button></div></label>${field('imageModel','绘图模型（可选）','text',state.settings.imageModel,'maxlength="100" placeholder="例如：gpt-image-1"')}<p id="api-status" class="api-status" role="status" aria-live="polite"></p><p class="notice">填写主机和密钥后点「拉取」，再选择聊天模型。绘图模型需按供应商实际名称填写；留空时朋友圈只生成文字。</p><div class="two-cols">${field('maxTokens','最大输出 token','number',state.settings.maxTokens,'min="256" max="65536"')}${field('contextChars','近期原文预算','number',state.settings.contextChars,'min="5000" max="12000"')}</div><label class="setting-row"><span>流式显示</span><input class="switch" name="stream" type="checkbox" ${state.settings.stream?'checked':''}></label><label class="setting-row"><span>记住密钥<small>仅存此设备；默认只保存至当前会话结束</small></span><input class="switch" name="remember" type="checkbox" ${remembered?'checked':''}></label><button class="primary wide" type="submit">保存 API 配置</button></form><p class="notice">聊天接口：/chat/completions；绘图接口：/images/generations。AI 判断动态适合配图时，绘图会成为第二次 API 请求，供应商可能另外计费。</p><p class="notice">密钥仅发往你填写的 API 主机，不进入备份。若中转不允许浏览器跨域访问，网页版直连会失败，需要供应商支持或另配服务端代理。</p>`}
function dataView(){return `<section class="setting-section"><h2>聊天小互动</h2>${switchField('interactions','允许 Claude 使用表情和虚拟卡片','开启后会附带简短的使用格式说明')}<button class="secondary wide" data-action="stickers">打开表情包收藏夹</button></section><section class="setting-section"><h2>戳一戳后缀</h2><form id="poke-form">${field('userPokeSuffix','别人戳你时接在名字后的文字','text',state.settings.userPokeSuffix,'maxlength="30" placeholder="的小脑袋"')}${field('aiPokeSuffix','你戳他时接在名字后的文字','text',state.settings.aiPokeSuffix,'maxlength="30" placeholder="的脸颊"')}<p class="notice">例如：${esc(state.settings.aiName)} 戳了戳 ${esc(state.settings.userName+state.settings.userPokeSuffix)}。留空就不加后缀。</p><button class="secondary wide">保存后缀</button></form></section><section class="setting-section"><h2>记录与备份</h2><p class="notice">${state.messages.length} 条聊天 · ${state.feed.length} 条动态 · ${state.letters.length} 封信 · ${state.memories.length} 条记忆。<br>记录只存在此浏览器，不会自动同步到另一台设备。</p><div class="action-list"><button class="secondary" data-action="export-chat">${icon('download')} 导出聊天 / 换地方继续</button><button class="secondary" data-action="export">完整小手机备份</button><button class="quiet danger" data-action="chat-reset" ${busy?'disabled':''}>清空聊天，重新开始</button><label class="upload-btn">${icon('upload')} 导入备份<input hidden type="file" accept="application/json,.json" id="import-file"></label></div><p class="notice">备份含聊天、头像和自存表情，不包含 API 密钥。换设备或清理浏览器前请先备份。</p></section><section class="setting-section"><h2>iPhone 使用</h2><p class="notice">线上地址在 Safari 打开后，可以选择「分享 → 添加到主屏幕」。电脑的 file:// 和 127.0.0.1 地址不能直接在手机打开。</p></section>`}
function openModal(title,html,modalClass=''){$('#modal').className=modalClass;$('#modal-content').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="modal-close" data-action="close" aria-label="关闭窗口">${icon('x')}</button></div>${html}`;if(!$('#modal').open)$('#modal').showModal();if(motionOK())gsap.fromTo('#modal-content',{opacity:0,y:14,scale:.985},{opacity:1,y:0,scale:1,duration:.28,ease:'power2.out',clearProps:'transform,opacity'})}
function closeModal(){const modal=$('#modal');modal.close();modal.className=''}
function updateDraft(){state.draft=$('#message-input').value;$('#draft-count').textContent=[...state.draft].length+' 字';updateComposer()}
function updateComposer(){updateQuotePreview();const text=$('#message-input').value.trim(),send=$('#send-button'),button=$('#reply-button');send.disabled=busy||!text;button.dataset.action=busy?'stop':'finish';button.textContent=busy?'停止回复':'让他回复';button.disabled=!busy&&!text&&state.messages.at(-1)?.role!=='user';button.setAttribute('aria-label',busy?'停止回复':'我说完了，让他回复');const c=context([],undefined,false,false),token=$('#token-count'),last=state.stats.lastInputTokens??state.stats.lastTokens;$('#turn-count').textContent='轮次 '+state.stats.turns;token.textContent=(state.stats.lastInputTokens!==null?'上下文 ':state.stats.lastTokens!==null?'本轮 ':'上下文 ')+(last===null?'—':last.toLocaleString('zh-CN'));token.title=last===null?'供应商返回用量后显示最近一轮':state.stats.lastInputTokens!==null?`本轮输入 ${state.stats.lastInputTokens.toLocaleString('zh-CN')}，输出 ${(state.stats.lastOutputTokens??0).toLocaleString('zh-CN')}，合计 ${(state.stats.lastTokens??last).toLocaleString('zh-CN')}；累计 ${state.stats.totalTokens.toLocaleString('zh-CN')}`:`最近一轮合计 ${last.toLocaleString('zh-CN')}；累计 ${state.stats.totalTokens.toLocaleString('zh-CN')}`;$('#context-hint').textContent=c.included<c.total?`下次发送最近 ${c.included} / ${c.total} 条历史；更早的记录仍保存在本机（文字与图片预算）。`:'';}
async function sendDraft(){if(busy){toast('等当前回复结束再发送');return}const text=$('#message-input').value.trim();if(!text)return;const source=state.messages.find(p=>p.id===quotedId&&!p.withdrawn),quoted=source?quoteContent(source,quotedPart):'';const m=addMessage('user',text);if(source)m.quote={id:source.id,role:source.role,content:quoted};quotedId='';quotedPart=-1;$('#message-input').value='';updateDraft();errorText='';render();bottom();await save()}
async function finishTurn(){if(busy)return;await sendDraft();if(busy)return;if(state.messages.at(-1)?.role!=='user'){toast('先发送一些话，再让他回复');return}await reply('retry')}
function bottom(){const v=$('#view');v.scrollTop=v.scrollHeight}
function stageFreshMessage(messageId){const article=[...document.querySelectorAll('.message[data-message-id]')].find(node=>node.dataset.messageId===messageId);if(!article)return;const pieces=[...article.querySelectorAll('[data-staged-piece]')],paced=state.settings.motion!==false&&!matchMedia('(prefers-reduced-motion: reduce)').matches;if(!paced){pieces.forEach(piece=>piece.classList.add('piece-pop'));article.classList.remove('fresh');bottom();return}let index=0;function show(){if(!article.isConnected)return;const piece=pieces[index++];if(!piece){article.classList.remove('fresh');return}piece.classList.add('piece-pop');const view=$('#view');requestAnimationFrame(()=>{if(article.isConnected)view.scrollTop=view.scrollHeight});if(index<pieces.length)setTimeout(show,360);else setTimeout(()=>article.classList.remove('fresh'),300)}show()}
function addMessage(role,content,parts){const m={id:id(),role,content,at:stamp(),...(parts?{parts}: {})};state.messages.push(m);return m}
function parseParts(raw,m,previous=[]){raw=processMemoryMarkers(raw,m);m.content=raw.trim();const used=new Set(),re=/\[\[(?:(表情|红包|外卖|领取|语音|音乐|撤回):([^\]\r\n]*)|(戳一戳))\]\]/g;let match,last=0,parts=[];while((match=re.exec(raw))){if(match.index>last)pushTextParts(parts,raw.slice(last,match.index));const [v,note='']=(match[2]||'').split('|'),old=previous.find(p=>p.marker===match[0]&&!used.has(p.id));if(old)used.add(old.id);let valid=false;if(!state.settings.interactions){parts.push({type:'text',text:match[0]});last=re.lastIndex;continue}if(match[3]==='戳一戳'){parts.push({type:'poke',suffix:state.settings.userPokeSuffix});valid=true}if(match[1]==='表情'&&allStickers().some(s=>s.id===v)){parts.push({type:'sticker',stickerId:v,animated:v==='puppy-5'});valid=true}if(match[1]==='红包'&&Number.isFinite(Number(v))&&Number(v)>0&&Number(v)<=10000){parts.push(old||{type:'gift',amount:Number(v),note:note.slice(0,100),id:id(),received:false,marker:match[0]});valid=true}if(match[1]==='外卖'&&v.trim()){parts.push(old||{type:'food',item:v.slice(0,100),note:note.slice(0,100),id:id(),received:false,marker:match[0]});valid=true}if(match[1]==='语音'&&v.trim()){parts.push({type:'voice',text:v.slice(0,2000)});valid=true}if(match[1]==='音乐'&&v.trim()){parts.push({type:'music',title:v.slice(0,100),artist:note.slice(0,100),note:(match[2].split('|')[2]||'').slice(0,200)});valid=true}if(match[1]==='撤回'&&m.role==='assistant'){const source=v==='自己'?m:state.messages.find(p=>p.id===v&&p.role==='assistant');if(source){withdrawMessage(source);parts.push({type:'text',text:'撤回了刚才的一条消息。'});valid=true}}if(match[1]==='领取'&&m.role==='assistant'){const source=state.messages.filter(x=>x.role==='user').flatMap(x=>x.parts||[]).find(p=>p.id===v&&['gift','food'].includes(p.type));if(source&&!source.received){source.received=true;parts.push({type:'claim',cardType:source.type,item:source.item,amount:source.amount,note:source.note,sourceId:source.id,id:id(),marker:match[0]});valid=true}else if(old?.type==='claim'&&old.sourceId===source?.id){parts.push(old);valid=true}}if(!valid)parts.push({type:'text',text:match[0]});last=re.lastIndex}if(last<raw.length)pushTextParts(parts,raw.slice(last));if(m.memorySavedCount)parts.push({type:'memory',text:'记下了 '+m.memorySavedCount+' 件小事',count:m.memorySavedCount});if(!m.withdrawn)m.parts=parts.filter(p=>p.type!=='text'||p.text);}
function endpoint(base=state.settings.base){const u=new URL(base);if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(u.hostname)))throw Error('API 主机需使用 HTTPS');if(u.username||u.password)throw Error('API 主机不要包含用户名或密码');u.hash='';u.pathname=u.pathname.replace(/\/$/,'');if(!u.pathname.endsWith('/chat/completions'))u.pathname+='/chat/completions';return u.toString()}
function imageEndpoint(base=state.settings.base){const u=new URL(base);if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(u.hostname)))throw Error('API 主机需使用 HTTPS');if(u.username||u.password)throw Error('API 主机不要包含用户名或密码');u.hash='';u.pathname=u.pathname.replace(/\/$/,'').replace(/\/chat\/completions$/,'');if(!u.pathname.endsWith('/images/generations'))u.pathname+='/images/generations';return u.toString()}
async function requestImage(prompt){if(!state.settings.imageModel)throw Error('尚未配置绘图模型');controller=new AbortController();const r=await fetch(imageEndpoint(),{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+apiKey},body:JSON.stringify({model:state.settings.imageModel,prompt,n:1,size:'1024x1024'}),signal:controller.signal});if(!r.ok)throw Error('绘图 API 返回 HTTP '+r.status);const data=await r.json(),item=data.data?.[0];if(item?.b64_json&&/^[A-Za-z0-9+/=]+$/.test(item.b64_json)&&item.b64_json.length<=16*1024*1024)return 'data:image/png;base64,'+item.b64_json;const remote=feedImageUrl(item?.url);if(remote)return remote;throw Error('绘图接口没有返回兼容的图片')}
async function request(messages,onText){if(!apiKey)throw Error('先在设置里填写 API 密钥。');const url=endpoint();controller=new AbortController();const body={model:state.settings.model,messages,max_tokens:state.settings.maxTokens,stream:state.settings.stream};if(body.stream)body.stream_options={include_usage:true};const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+apiKey},body:JSON.stringify(body),signal:controller.signal});if(!r.ok){const errors={401:'密钥未通过验证，请检查 API 密钥。',402:'供应商提示余额不足。',403:'供应商拒绝了请求，请检查权限。',429:'请求受限，请稍后手动再试。'};throw Error(errors[r.status]||'API 返回 HTTP '+r.status+'，请检查主机、模型或供应商限制。')}if(!state.settings.stream||!(r.headers.get('content-type')||'').includes('text/event-stream')){const data=await r.json();if(data.error)throw Error('供应商返回了错误。请检查配置。');const content=data.choices?.[0]?.message?.content;if(typeof content!=='string')throw Error('接口没有返回兼容格式的回复。');onText(content);return {reason:data.choices[0].finish_reason,usage:data.usage}}if(!r.body)throw Error('浏览器无法读取流式回复。');const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='',output='',reason=null,usage=null,done=false;function process(line){if(!line.startsWith('data:'))return;const data=line.slice(5).trim();if(data==='[DONE]'){done=true;return}if(!data)return;let parsed;try{parsed=JSON.parse(data)}catch{throw Error('流式数据格式不完整，已保留收到的文字。')}if(parsed.error)throw Error('供应商在回复中返回了错误。');if(parsed.usage)usage=parsed.usage;const choice=parsed.choices?.[0];if(choice?.finish_reason){reason=choice.finish_reason;done=true}const text=choice?.delta?.content;if(typeof text==='string'){output+=text;onText(output)}}while(true){const {value,done:ended}=await reader.read();if(ended)break;buffer+=decoder.decode(value,{stream:true});let pos;while((pos=buffer.indexOf('\n'))>=0){process(buffer.slice(0,pos).replace(/\r$/,''));buffer=buffer.slice(pos+1)}}buffer+=decoder.decode();if(buffer.trim())process(buffer.trim());if(!done)throw Error('回复连接中断，已保留收到的文字；不会自动重试。');return {reason,usage}}
async function reply(mode='retry',targetId){if(busy)return;if(!apiKey){tab='api';location.hash='settings';render();toast('先填写你的 API 配置');return}let target,previous=[],extra=[],untilId=targetId;const newTurn=mode!=='continue';if(mode==='continue'){target=state.messages.find(m=>m.id===targetId&&m.role==='assistant');if(!target||target.withdrawn)return;previous=target.parts||[];extra=[{role:'user',content:'请接着上一条未完成的回复继续写，不重复已有文字。'}]}else if(mode==='regenerate'){target=state.messages.find(m=>m.id===targetId&&m.role==='assistant');if(!target||target.withdrawn)return;previous=target.parts||[];const index=state.messages.indexOf(target),previousUser=state.messages.slice(0,index).reverse().find(m=>m.role==='user'&&!m.withdrawn);untilId=previousUser?.id;invalidateMemories([target.id]);target.content='';target.parts=[];target.memoryMarkers=[]}const c=context(extra,untilId,newTurn);if(c.included===0){toast('消息超过近期原文预算，请缩短最后一条消息或减少附件。');await save();render();return}const prefix=target?.content||'';let received='';if(!target)target=addMessage('assistant','');target.memoryCheck=c.memoryCheck;target.memorySourceIds=c.memorySourceIds;target.pending=true;target.partial=false;target.failed=false;delete target.failure;busy=true;errorText='';await save();render();bottom();try{const result=await request(c.messages,text=>received=text);target.content=prefix+(prefix&&received?'\n':'')+received;if(newTurn)state.stats.turns++;const usage=usageStats(result.usage);if(usage.total!==null){state.stats.totalTokens+=usage.total;state.stats.tokenReports++}if(usage.total!==null||usage.input!==null||usage.output!==null){state.stats.lastTokens=usage.total;state.stats.lastInputTokens=usage.input;state.stats.lastOutputTokens=usage.output}target.partial=result.reason==='length';target.failed=false;delete target.failure;if(state.settings.interactions||state.settings.aiMemory)parseParts(target.content,target,previous);else target.parts=splitReplyText(target.content).map(text=>({type:'text',text}));if(c.recallIds.length){const recalledAt=stamp(),recalledIds=new Set(c.recallIds);for(const memory of state.memories)if(recalledIds.has(memory.id)){memory.lastRecalledAt=recalledAt;memory.recallCount++}}if(c.memoryCheck&&newTurn){state.memoryMeta.lastExtractionTurn=state.stats.turns;state.memoryMeta.lastExtractionMessageId=target.id}if(result.reason==='length')toast('已到供应商输出上限，可以点「继续说完」（新请求）。')}catch(e){target.memoryCheck=false;if(received){target.content=prefix+(prefix?'\n':'')+received;if(state.settings.interactions||state.settings.aiMemory)parseParts(target.content,target,previous);else target.parts=splitReplyText(target.content).map(text=>({type:'text',text}))}errorText=e.name==='AbortError'?'已停止，收到的回复已保留。':e instanceof TypeError?'连接失败。请检查网络、API 主机和供应商跨域支持；没有自动重试。':e.message;target.partial=!!String(target.content||'').trim();target.failed=true;target.failure=errorText}finally{target.pending=false;busy=false;controller=null;await save();freshMessageId=received?target.id:'';render();freshMessageId='';stageFreshMessage(target.id)}}
async function generate(kind,theme=LETTER_THEMES.normal){if(busy)return null;if(!apiKey){tab='api';location.hash='settings';render();toast('先填写 API 配置');return null}const recent=state.feed.filter(post=>(post.role||'assistant')==='assistant').slice(-4).map(post=>plainContent(post.content).slice(0,80)).join(' / '),imageInstruction=state.settings.imageModel?'如果这条动态确实适合用画面表达，你可以自行决定配图，并在正文末尾另起一行写 [[配图:20至120字的具体画面描述]]；不需要配图时不要写该标记。配图里不要出现文字、水印或界面。':'当前没有配置绘图模型，不要输出配图标记。',prompt=kind==='feed'?`请像真实用户随手发状态，不要写成精心组织的文章。内容可以只有几个字、一两句话、碎片化表达或偶尔稍完整的一段；可以不加标点，用语气词、口语、聊天里自然出现过的网络用语或方言收尾。格式元素自然随机：偶尔使用1至2个emoji或颜文字，也可以使用省略号、破折号、情绪化的“？？？”“！！”，或偶尔加一个贴合内容的话题标签；不要每条都使用同一种格式。内容可以是基于真实聊天的即时感受、碎碎念、轻度吐槽、小确幸、状态变化或偶尔的低落情绪；有时可以只发一个系统提供的 [[表情:ID]]、一个emoji或几个标点。不要总结聊天、写关系回顾或用“今天我们聊了”开头；不要写长段分析，不要每条都深刻、文学化或意义完整，也不要故意制造错别字。可以从最近聊天得到灵感，但不得虚构现实经历、天气、地理位置、工作、出游或线下活动。正文1至200个中文字，不写额外标题、@某人或字数说明。发布时间由系统记录真实生成时间，不要在正文中编造时间。${recent?'避免重复这些近期动态：'+recent+'。':''}${imageInstruction}`:`请参考我们最近的聊天，以“${theme.name}”为主题，写一封给我的私人信件。${theme.prompt} 信件应有完整的开头、情感展开和收束，可以回顾确实发生过的共同聊天和记忆、表达此刻感受并展望未来；不得编造现实经历，也不要声称透露隐藏思维。正文控制在300至800个中文字，只写信正文，不写标题、字数说明或提示词。可以自然使用一个系统提供的 [[表情:ID]]，除此之外不用格式标记。`;busy=true;render();let content='',savedRecord=null,image='',imageFailure='';try{const c=context([{role:'user',content:prompt}]);await request(c.messages,t=>content=t);if(kind==='feed'){const match=content.match(/\s*\[\[配图:([\s\S]{10,800}?)\]\]\s*$/);if(match){content=content.slice(0,match.index).trim();try{image=await requestImage(match[1].trim())}catch(e){imageFailure=e.name==='AbortError'?'已停止生成配图':e.message||'配图生成失败'}}content=[...content.trim()].slice(0,200).join('')}const record={id:id(),at:stamp(),content,...(image?{image}:{}),...(kind==='letter'?{occasionKey:theme.key,occasionName:theme.name,occasionDate:theme.date||localDateKey(new Date())}:{})};if(kind==='feed')state.feed.push({...record,role:'assistant',liked:false,comments:[]});else state.letters.push(record);savedRecord=record;await save();toast(kind==='feed'?(imageFailure?'动态已保存，但'+imageFailure:'新动态已保存'):theme.name+'的信已保存')}catch(e){if(content){openModal('未完成的文字',`<div class="letter-paper">${esc(content)}</div><p class="notice">连接中断，未自动重试。这段文字尚未存入列表，请复制保存。</p>`)}toast(e.name==='AbortError'?'已停止生成':e instanceof TypeError?'连接失败，请检查主机与跨域支持':e.message)}finally{busy=false;controller=null;render()}return savedRecord}
function stickerModal(){openModal('表情包收藏夹',`<p class="notice">双方共用同一个收藏夹。点选即可发送，双方都能用。说完再点「让他回复」，才会调用 API。</p><div class="sticker-grid">${allStickers().map(s=>`<div><button data-action="sticker-send" data-id="${s.id}" aria-label="发送${esc(s.name)}">${stickerHTML(s,s.id==='puppy-5')}<small>${esc(s.name)}</small></button>${state.stickers.some(item=>item.id===s.id)?`<button class="quiet" data-action="sticker-delete" data-id="${s.id}">删除</button>`:''}</div>`).join('')}</div><label class="upload-btn wide">${icon('upload')} 存入表情（可多选）<input hidden type="file" multiple accept="image/png,image/jpeg,image/gif,image/webp" data-upload="stickers"></label><p class="notice">支持静图和动态图，每张不超过 8MB。内置 ${lineDogs.length} 张韩国线条小狗动态表情，另保留原来的 6 张原创小狗。上传动态图会保留动画。<br>线条小狗：© MALTESE / Moonlab_studio；<a href="https://github.com/gzzzxx/emo/tree/master/linedog" target="_blank" rel="noopener noreferrer">资源来源</a>。</p>`)}
async function interaction(parts,content){if(busy){toast('等当前回复结束再发送');return}addMessage('user',content,parts);await save();closeModal();location.hash='chat';render();bottom();toast('已发送；说完再点「让他回复」')}

function apiMessage(m){const images=m.role==='user'?(m.parts||[]).filter(p=>p.type==='image'&&imageUrl(p.src)):[];return {role:m.role,content:images.length?[...images.map(p=>({type:'image_url',image_url:{url:p.src}})),{type:'text',text:messageText(m)}]:messageText(m)}}
function mediaUrl(p){return p.type==='image'?imageUrl(p.src):/^data:video\/(mp4|webm|quicktime);base64,[A-Za-z0-9+/=]+$/.test(p.src||'')?p.src:''}
function mediaHTML(p){const src=mediaUrl(p);if(!src)return '';return `<figure class="chat-media">${p.type==='image'?`<img src="${src}" alt="${esc(p.name)}" loading="lazy">`:`<video src="${src}" controls playsinline preload="metadata" aria-label="${esc(p.name)}"></video>`}<figcaption>${esc(p.name)}${p.type==='video'?' · 本地视频':''}</figcaption></figure>`}
async function albumModal(files){
 if(busy)throw Error('等当前回复结束再发送');
 if(files.length>4)throw Error('一次最多选 4 个文件');
 if(files.reduce((n,f)=>n+f.size,0)>24*1024*1024)throw Error('一次选择的文件合计不超过 24MB');
 if(files.filter(f=>f.type.startsWith('image/')).reduce((n,f)=>n+f.size,0)>12*1024*1024)throw Error('一条消息的图片合计不超过 12MB');
 for(const f of files){const image=/^image\/(png|jpeg|gif|webp)$/.test(f.type),video=/^video\/(mp4|webm|quicktime)$/.test(f.type);if(!image&&!video)throw Error('支持 JPG、PNG、GIF、WebP 图片和 MP4、WebM、MOV 视频；HEIC 请转为 JPG');if(f.size>(image?8:20)*1024*1024)throw Error(image?'每张图片不超过 8MB':'每段视频不超过 20MB');}
 const parts=await Promise.all(files.map(async f=>({type:f.type.startsWith('image/')?'image':'video',name:f.name.slice(0,100),src:await fileData(f)})));
 if(busy)throw Error('等当前回复结束再发送');
 openModal('发送相册',`<form id="album-form"><div class="album-preview">${parts.map(mediaHTML).join('')}</div><label class="form-field"><span>附上一句话（可不填）</span><textarea name="caption" placeholder="想和他分享什么？" maxlength="10000"></textarea></label><p class="notice">点「让他回复」后，图片会随聊天发送给你配置的 API（需中转支持看图）。视频保存在本机聊天，可播放；画面不直接传给模型。发送相册不会立即调用 API。<br>JPG / PNG / GIF / WebP ≤ 8MB；MP4 / WebM / MOV ≤ 20MB，能否播放取决于设备编码支持。</p><button class="primary wide">发送</button></form>`);
 albumParts=parts;
}


function messageText(m){const files=m.role==='user'?(m.parts||[]).filter(p=>p.type==='file'&&typeof p.text==='string'):[];if(m.withdrawn)return '['+(m.role==='user'?'用户':'助手')+'撤回了一条消息；ID='+m.id+']';const quoted=m.quote?'[用户正在引用'+(m.quote.role==='user'?state.settings.userName:state.settings.aiName)+'的一条消息；消息ID='+m.quote.id+'；引用原文：'+m.quote.content+']\n':'';return quoted+m.content+files.map(p=>'\n\n--- 用户提供的文件：'+p.name+' ---\n'+p.text+'\n--- 文件内容结束 ---').join('')}
function pokeHTML(m){const user=m.role==='user',s=state.settings;return `<div class="poke-event ${user?'user-poke':'ai-poke'}">${icon('heart')}<span>${esc(user?s.userName:s.aiName)} 戳了戳 ${esc((user?s.aiName:s.userName)+(m.parts?.find(p=>p.type==='poke')?.suffix||''))}</span></div>`}
function fileUrl(src){return /^data:[a-z0-9.+-]+\/[a-z0-9.+-]+;base64,[A-Za-z0-9+/=]*$/i.test(src||'')?src:''}
function fileHTML(m,p){return `<button class="chat-file" data-action="file-download" data-id="${m.id}">${icon('download')}<span><strong>${esc(p.name)}</strong><small>${Math.ceil(p.size/1024)} KB · ${p.text!==undefined?'文本已附上':'文件保存在本机'} · 下载</small></span></button>`}
function downloadFile(p){const src=fileUrl(p.src);if(!src)return;const bytes=Uint8Array.from(atob(src.split(',')[1]),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:src.slice(5,src.indexOf(';'))})),a=document.createElement('a');a.href=url;a.download=p.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
async function fileModal(file){
 if(busy)throw Error('等当前回复结束再发送');if(file.size>10*1024*1024)throw Error('每个文件不超过 10MB');
 const part={type:'file',name:file.name.slice(0,100),size:file.size,src:await fileData(file)};
 if(/\.(txt|md|csv|json|log)$/i.test(file.name)){const text=await file.text();part.text=text.slice(0,50000);part.truncated=text.length>50000;}
 if(!fileUrl(part.src))throw Error('文件格式无法保存');if(busy)throw Error('等当前回复结束再发送');
 openModal('发送文件',`<form id="file-form"><div class="file-preview">${icon('download')}<strong>${esc(part.name)}</strong><p>${Math.ceil(file.size/1024)} KB</p></div>${part.text!==undefined?`<pre class="file-text-preview">${esc(part.text.slice(0,1200))}</pre>`:''}<p class="notice">${part.text!==undefined?'文本正文会在「让他回复」时发给 Claude'+(part.truncated?'；文件较长，只附前 50000 字。':'。'):'这个格式目前只保存文件和文件名，尚未解析正文；Claude 无法直接阅读。'}<br>附件保存在本机，可在聊天里下载。发送不会立即调用 API。</p><button class="primary wide">发送文件</button></form>`);
 filePart=part;
}

function memoryModal(existing,text=''){const type=existing?.type==='legacy'?'fact':existing?.type||'fact';openModal(existing?'编辑记忆':'添加记忆',`<form id="memory-v2-form" data-id="${existing?.id||''}"><label class="form-field"><span>放在哪一页？</span><select name="type"><option value="fact" ${type==='fact'?'selected':''}>始终记得</option><option value="episode" ${type==='episode'?'selected':''}>我们的经历</option><option value="thread" ${type==='thread'?'selected':''}>下次接着聊</option></select></label><label class="form-field"><span>记忆内容（2—120 个字）</span><textarea name="text" required minlength="2" maxlength="120">${esc(existing?.text||text)}</textarea></label><label class="form-field"><span>关键词（可选，用逗号分开）</span><input name="keywords" maxlength="100" value="${esc((existing?.keywords||[]).join('，'))}" placeholder="例如：咖啡，雨天，纪念日"></label>${existing?`<p class="notice">手动保存后，这条记忆会被确认并由你管理，不再随来源消息自动失效。</p>`:''}<div class="modal-actions">${existing?`<button type="button" class="danger" data-action="memory-delete" data-id="${existing.id}">删除</button>`:''}<button class="primary">保存记忆</button></div></form>`)}
function download(data,name,type='application/json'){const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
async function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
async function upload(file,kind){if(!/^image\/(png|jpeg|gif|webp)$/.test(file.type)||file.size>8*1024*1024)throw Error('请选择不超过 8MB 的 PNG、JPG、GIF 或 WebP');const src=await fileData(file);if(kind==='stickers'){state.stickers.push({id:id(),name:file.name.replace(/\.[^.]+$/,'').slice(0,30)||'表情',src});return}const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=src});const max=kind==='wallpaper'?1400:256,ratio=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*ratio);canvas.height=Math.round(img.height*ratio);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);state.settings[kind]=canvas.toDataURL('image/webp',.85)}
function validBackup(data){if(![1,2].includes(data?.version)||!data.settings)throw Error('不是月隙的备份文件');validateBackupFields(data);for(const key of ['messages','feed','letters','memories','stickers'])if(!Array.isArray(data[key])||data[key].length>30000)throw Error('备份结构不正确');if(data.messages.some(m=>!['user','assistant'].includes(m.role)||typeof m.content!=='string'||typeof m.id!=='string'))throw Error('聊天记录格式不正确');for(const key of ['feed','letters'])if(data[key].some(m=>typeof m.content!=='string'||typeof m.id!=='string'))throw Error('内容格式不正确');if(data.memories.some(m=>typeof m.text!=='string'||typeof m.id!=='string')||data.stickers.some(s=>typeof s.id!=='string'||!imageUrl(s.src)))throw Error('记忆或表情格式不正确');const settings=migrateFrames({...DEFAULT,...Object.fromEntries(Object.keys(DEFAULT).filter(k=>k in data.settings).map(k=>[k,data.settings[k]]))});settings.contextChars=Math.min(12000,settings.contextChars);return {version:2,profiles:profilesOf(data.profiles),health:healthOf(data.health),music:musicOf(data.music),stats:statsOf(data.stats,data.messages),settings,messages:data.messages,feed:data.feed,letters:data.letters,memories:data.memories.map(memoryOf),memoryMeta:memoryMetaOf(data.memoryMeta),stickers:data.stickers,draft:typeof data.draft==='string'?data.draft:''}}
function motionOK(){return state.settings.motion!==false&&!!window.gsap&&!matchMedia('(prefers-reduced-motion: reduce)').matches}
function animateRoute(){if(!motionOK())return;const items=[...$('#view').children].slice(0,8);gsap.fromTo(items,{opacity:0,y:8},{opacity:1,y:0,duration:.3,stagger:.035,ease:'power2.out',clearProps:'transform,opacity'});const active=$('.dock .active');if(active)gsap.fromTo(active,{scale:.94},{scale:1,duration:.28,ease:'back.out(1.7)',clearProps:'transform'})}
